def sherlock_and_anagrams(s: str) -> int:
    from collections import Counter
    subs = Counter()
    n = len(s)
    for length in range(1, n):
        for i in range(n - length + 1):
            sub = ''.join(sorted(s[i:i + length]))
            subs[sub] += 1
    return sum(v * (v - 1) // 2 for v in subs.values())
